<?php require_once __DIR__.'/../bootstrap.php';require_admin();$defaults=['Japanese SUB','English SUB','English DUB','Hindi DUB','Bengali DUB','Tamil DUB','Telugu DUB','Malayalam DUB','Kannada DUB','Other'];$pdo->exec('CREATE TABLE IF NOT EXISTS languages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL,active TINYINT(1) DEFAULT 1) ENGINE=InnoDB');foreach($defaults as $d)$pdo->prepare('INSERT IGNORE INTO languages(name) VALUES(?)')->execute([$d]);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['delete']))$pdo->prepare('DELETE FROM languages WHERE id=? AND name NOT IN ('.implode(',',array_fill(0,count($defaults),'?')).')')->execute(array_merge([(int)$_POST['id']],$defaults));else if(isset($_POST['add']))$pdo->prepare('INSERT IGNORE INTO languages(name) VALUES(?)')->execute([trim($_POST['name'])]);else $pdo->prepare('UPDATE languages SET name=?,active=? WHERE id=?')->execute([trim($_POST['name']),isset($_POST['active'])?1:0,(int)$_POST['id']]);header('Location: languages.php');exit;}$title='Languages — AniRead';include __DIR__.'/../includes/header.php';?><h1>Languages</h1><form class="filters" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input class="input" name="name" placeholder="New language" required><button class="btn" name="add">Add</button></form><table class="table"><tr><th>Language</th><th>Active</th><th></th></tr><?php foreach($pdo->query('SELECT * FROM languages ORDER BY name') as $l):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$l['id']?>"><td><input class="input" name="name" value="<?=e($l['name'])?>"></td><td><input type="checkbox" name="active" <?=$l['active']?'checked':''?>></td><td><button class="btn alt">Save</button><button class="btn alt" name="delete" data-confirm="Delete this language?">Delete</button></td></form></tr><?php endforeach;?></table><?php include __DIR__.'/../includes/footer.php';
